ITEM(REG,ID,STATUS,FAMILY,KIND,TITLE,DESC,PHASE,TEST,PATH,SMOKEPAGE,TOKEN)
	N N
	S N=$O(REG(""),-1)+1
	S REG(N,"id")=$G(ID)
	S REG(N,"status")=$G(STATUS)
	S REG(N,"family")=$G(FAMILY)
	S REG(N,"kind")=$G(KIND)
	S REG(N,"title")=$G(TITLE)
	S REG(N,"desc")=$G(DESC)
	S REG(N,"phase")=$G(PHASE)
	S REG(N,"test")=$G(TEST)
	S REG(N,"path")=$G(PATH)
	S REG(N,"smokePage")=$G(SMOKEPAGE)
	S REG(N,"token")=$G(TOKEN)
	Q
	;
COUNT(REG,STATUS)
	N I,C
	S (I,C)=0
	F  S I=$O(REG(I)) Q:'I  D
	. I $G(STATUS)="",$D(REG(I,"id")) S C=C+1 Q
	. I $G(REG(I,"status"))=$G(STATUS) S C=C+1
	Q C
	;
FIND(REG,ID)
	N I
	S I=0
	F  S I=$O(REG(I)) Q:'I  I $G(REG(I,"id"))=$G(ID) Q
	Q I
	;